/* ЖРЕБИЙ, КОМАНДЫ, ТАЙНЫЙ САНТА, ЛОТО.
   Список берётся из выделения (один столбец имён; для команд второй столбец — роль).
   Результат пишется справа от списка, с отметкой времени и порядком жеребьёвки —
   чтобы любой мог проверить, как всё было. Случайность — криптографический генератор. */

/* ===== Поле на клетках листа: общий кусок игр магазина =====
   Строки и столбцы здесь — С НУЛЯ (r, c); адреса A1 считаются отсюда же.
   ячейка(строка, столбец) API плагина считает с единицы — поэтому везде «+ 1». */
const БУКВА = c => { let s = '', n = c + 1; while(n > 0){ const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = (n - 1 - m) / 26; } return s; };
const АДРЕС = (r, c) => БУКВА(c) + (r + 1);
const ОБЛАСТЬ = (r1, c1, r2, c2) => АДРЕС(r1, c1) + ':' + АДРЕС(r2, c2);
const клетка = (r, c) => ячейка(r + 1, c + 1);
/* Квадратные клетки: ширина столбца в знаках (знак — 7 точек), высота строки в пунктах (×4/3 точки). */
function клеткиКвадратом(r1, c1, r2, c2, точек){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(точек / 7);
  о.SetRowHeight(точек * 0.75);
}
/* Вернуть области обычные размеры клеток (столбец 92 точки, строка 24 точки = 18 пунктов). */
function обычныеРазмеры(r1, c1, r2, c2){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(92 / 7);
  о.SetRowHeight(18);
}
/* Ширина одного столбца и высота одной строки в точках экрана. */
function ширинаСтолбца(c, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c, 0, c)).SetColumnWidth(точек / 7); }
function высотаСтроки(r, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r, 0, r, 0)).SetRowHeight(точек * 0.75); }
/* Приложение запоминает смещения строк и не сбрасывает их, когда плагин меняет высоты строк:
   после этого щелчок мыши попадает не в ту клетку. Пустая запись в далёкую пустую строку
   растит сетку листа, и смещения пересчитываются. Звать после смены высот. */
async function обновитьВысоты(){
  /* каждый раз — строка дальше прежней: сетка растёт, только если запись за её краем */
  let n = 0; try { n = +лист().память('высоты-шаг') || 0; } catch(e){}
  for(let k = n + 1; k <= n + 40; k++){
    const r = 5999 + k;
    let v = null;
    try { v = await клетка(r, 0).прочитать(); } catch(e){ continue; }
    if(v === null || v === undefined || v === ''){
      клетка(r, 0).значение = null;
      try { лист().запомнить('высоты-шаг', k); } catch(e){}
      return true;
    }
  }
  return false;
}
/* Курсор — на «стоянку» рядом с полем. Тогда повторный щелчок по той же клетке
   снова сменит выделение, и плагин получит событие: иначе второй щелчок молчал бы. */
function наСтоянку(r, c){ клетка(r, c).выделить(); }
/* Пуста ли область листа: игра не должна молча затирать чужие данные. */
async function областьПуста(r1, c1, r2, c2){
  const строки = await диапазон(ОБЛАСТЬ(r1, c1, r2, c2)).прочитать();
  for(const ряд of строки || []) for(const v of ряд || []) if(v !== null && v !== undefined && v !== '') return false;
  return true;
}
/* Рамка: все четыре стороны одним видом. */
const РАМКА = (вид, цвет) => ({в: {вид, цвет}, н: {вид, цвет}, л: {вид, цвет}, п: {вид, цвет}});
/* Число со словом в нужной форме: число(5, 'выстрел', 'выстрела', 'выстрелов') → «5 выстрелов». */
function число(n, одна, две, пять){ const a = Math.abs(n) % 100, b = a % 10;
  return n + ' ' + (a > 10 && a < 20 ? пять : b === 1 ? одна : b >= 2 && b <= 4 ? две : пять); }
/* Время «м:сс». */
const ВРЕМЯ = с => Math.floor(с / 60) + ':' + String(Math.floor(с % 60)).padStart(2, '0');
/* Повод события — клетка с нуля и на нужном ли листе. */
function гдеЩелчок(п, лист){
  if(!п || !п.адрес || (лист && п.лист !== лист)) return null;
  if(п.клеток > 1) return null;                     /* протянули мышью область — это не ход */
  return {r: п.строка - 1, c: п.столбец - 1};
}
/* Защита от «правой кнопки»: правый щелчок сначала зовёт меню, а через 150 мс
   приходит выделение той же клетки. Такой выбор ходом не считаем. */
let последнееМеню = {адрес: '', t: 0};
const этоПослеМеню = п => п && п.адрес === последнееМеню.адрес && Date.now() - последнееМеню.t < 1500;
/* ===== конец общего куска ===== */
/* Оформление области по клеткам. Api GetRange(…).SetNumberFormat и другие оформления области из потока
   задевают только ту часть, что была занята при запуске потока, — свежие строки остаются без оформления.
   л — лист плагина: лист(имя) или черновик; строки и столбцы — с нуля. */
function оформитьОбласть(л, r1, c1, r2, c2, стиль){
  if((r2 - r1 + 1) * (c2 - c1 + 1) > 300000) return false;
  for(let r = r1; r <= r2; r++) for(let c = c1; c <= c2; c++) л.ячейка(r + 1, c + 1).стиль = стиль;
  return true;
}

const ПАМЯТЬ_ЛОТО = 'лото';
const ЗАГ = {b: 1, color: '#151c2e'};
const ТОНКАЯ = РАМКА('тонкая', '#9aa4b5');

function случайное(n){
  try {
    const a = new Uint32Array(1), предел = Math.floor(0x100000000 / n) * n;
    do { crypto.getRandomValues(a); } while(a[0] >= предел);
    return a[0] % n;
  } catch(e){ return Math.floor(Math.random() * n); }
}
function перемешать(м){ const a = м.slice(); for(let i = a.length - 1; i > 0; i--){ const j = случайное(i + 1); [a[i], a[j]] = [a[j], a[i]]; } return a; }
const два = n => String(n).padStart(2, '0');
function сейчас(){ const d = new Date(); return два(d.getDate()) + '.' + два(d.getMonth() + 1) + '.' + d.getFullYear() + ' ' + два(d.getHours()) + ':' + два(d.getMinutes()) + ':' + два(d.getSeconds()); }
const пауза = мс => new Promise(r => setTimeout(r, мс));

/* --- список из выделения --- */
/* \b в регулярных выражениях JS не знает русских букв — граница слова задана явно */
const ЗАГОЛОВОК = /^(имя|имена|фио|ф\.и\.о\.?|участник|участники|сотрудник|сотрудники|фамилия|кто|name|names|роль|должность|отдел|команда|список)(?![а-яёa-z])/i;
async function список(нужноСтолбцов){
  const в = книга.выделение;
  if(!в || !в.область || (в.r2 === в.r1 && в.c2 === в.c1)){ панель.сообщение('Выделите список: имена в столбце (можно с заголовком).'); return null; }
  const строки = await диапазон(в.область).прочитать();
  let ряды = (строки || []).map(р => (р || []).slice(0, нужноСтолбцов).map(x => x == null ? '' : String(x).trim()));
  let заголовок = null;
  if(ряды.length && ЗАГОЛОВОК.test(ряды[0][0] || '')){ заголовок = ряды[0]; ряды = ряды.slice(1); }
  ряды = ряды.filter(р => р[0]);
  /* повторы имён — частая ошибка списка: предупреждаем, но не выбрасываем молча */
  const виделиИмена = new Map(); for(const р of ряды) виделиИмена.set(р[0], (виделиИмена.get(р[0]) || 0) + 1);
  const повторы = [...виделиИмена].filter(([, n]) => n > 1).map(([и]) => и);
  return {в, ряды, заголовок, повторы};
}
/* Куда писать результат: справа от выделения, через столбец; занято — двигаемся дальше вправо. */
async function местоДля(в, ширина, высота){
  let c = в.c2 + 1;                       /* в.c2 — номер с единицы; c — с нуля: через один пустой столбец */
  const r = в.r1 - 1;
  for(let k = 0; k < 12; k++){
    if(await областьПуста(r, c, r + высота - 1, c + ширина - 1)) return {r, c};
    c += ширина + 1;
  }
  return null;
}
function написать(r, c, значение, стиль){ const к = клетка(r, c); к.значение = значение; if(стиль) к.стиль = стиль; }

/* --- жребий --- */
async function Выбрать(){
  const сп = await список(1);
  if(!сп) return;
  const п = параметры({});
  const k = Math.max(1, Math.min(сп.ряды.length, Math.floor(+п.сколько || 1)));
  if(сп.ряды.length < 1){ панель.сообщение('В выделении нет имён.'); return; }
  const место = await местоДля(сп.в, 2, k + 2);
  if(!место){ панель.сообщение('Справа от списка нет свободного места для результата.'); return; }
  /* барабан: имена мелькают в панели, затем останавливается на победителе */
  const имена = сп.ряды.map(р => р[0]);
  const порядок = перемешать(имена).slice(0, k);
  const t0 = Date.now();
  while(Date.now() - t0 < 1600){
    панель.поле('барабан', [{текст: '  ' + имена[случайное(имена.length)] + '  ', жирный: true, фон: '#eef3fe', цвет: '#296DF4'}]);
    await пауза(70);
  }
  панель.поле('барабан', порядок.map((и, n) => ({текст: (n ? '   ' : '') + (n + 1) + '. ' + и, жирный: true, цвет: '#15803d'})));
  const {r, c} = место;
  написать(r, c, 'Жребий ' + сейчас() + ': ' + k + ' из ' + имена.length, ЗАГ);
  написать(r + 1, c, '№', ЗАГ); написать(r + 1, c + 1, 'Выбран', ЗАГ);
  порядок.forEach((и, n) => { написать(r + 2 + n, c, n + 1, {align: 'center'}); написать(r + 2 + n, c + 1, и); });
  Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c + 1, 0, c + 1)).SetColumnWidth(Math.max(14, Math.min(40, Math.max(...порядок.map(x => x.length)) + 2)));
  панель.сообщение('Выбрано: ' + порядок.join(', ') + '. Результат с отметкой времени — справа от списка, в ' + АДРЕС(r, c) + '.'
    + (сп.повторы.length ? ' Внимание: в списке есть повторы (' + сп.повторы.slice(0, 3).join(', ') + ') — у них больше шансов.' : ''));
}

/* --- команды --- */
async function Разделить(){
  const сп = await список(2);
  if(!сп) return;
  const п = параметры({});
  const к = Math.max(2, Math.floor(+п.команд || 2));
  if(сп.ряды.length < к){ панель.сообщение('Людей (' + сп.ряды.length + ') меньше, чем команд (' + к + ').'); return; }
  const сРолями = сп.ряды.some(р => р[1]);
  /* по ролям: каждую роль раздаём по кругу, начиная с самой маленькой команды — так и роли, и размеры ровные */
  const группы = new Map();
  for(const р of перемешать(сп.ряды)){ const роль = сРолями ? (р[1] || 'без роли') : ''; if(!группы.has(роль)) группы.set(роль, []); группы.get(роль).push(р); }
  const команды = Array.from({length: к}, () => []);
  const роли = [...группы.keys()].sort((a, b) => группы.get(b).length - группы.get(a).length);
  for(const роль of роли){
    for(const р of группы.get(роль)){
      const мин = Math.min(...команды.map(x => x.length));
      const кандидаты = команды.map((x, i) => i).filter(i => команды[i].length === мин);
      /* среди самых маленьких — та, где этой роли меньше */
      const сколькоРоли = i => команды[i].filter(x => (x[1] || 'без роли') === (р[1] || 'без роли')).length;
      const мр = Math.min(...кандидаты.map(сколькоРоли));
      const выбор = кандидаты.filter(i => сколькоРоли(i) === мр);
      команды[выбор[случайное(выбор.length)]].push(р);
    }
  }
  const высота = Math.max(...команды.map(x => x.length)) + 2;
  const место = await местоДля(сп.в, к, высота);
  if(!место){ панель.сообщение('Справа от списка нет свободного места для команд.'); return; }
  const {r, c} = место;
  написать(r, c, 'Команды ' + сейчас() + ': ' + сп.ряды.length + ' чел. на ' + к + (сРолями ? ', поровну по ролям' : ''), ЗАГ);
  команды.forEach((x, i) => {
    написать(r + 1, c + i, 'Команда ' + (i + 1) + ' (' + x.length + ')', Object.assign({fill: '#eef3fe', гр: ТОНКАЯ}, ЗАГ));
    x.forEach((р, n) => написать(r + 2 + n, c + i, р[0] + (сРолями && р[1] ? ' — ' + р[1] : ''), {гр: ТОНКАЯ}));
  });
  const шир = Math.max(14, Math.min(40, Math.max(...сп.ряды.map(р => (р[0] + (р[1] ? ' — ' + р[1] : '')).length)) + 2));
  Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c, 0, c + к - 1)).SetColumnWidth(шир);
  панель.сообщение('Готово: ' + к + ' команд по ' + команды.map(x => x.length).join(', ') + ' человек' + (сРолями ? '; роли разложены поровну' : '') + '. Таблица — в ' + АДРЕС(r, c) + '.');
}

/* --- Тайный Санта: один общий круг — никто не дарит сам себе и пары не замыкаются друг на друга --- */
async function Санта(){
  const сп = await список(1);
  if(!сп) return;
  const имена = [...new Set(сп.ряды.map(р => р[0]))];
  if(имена.length < 3){ панель.сообщение('Для Тайного Санты нужно хотя бы три человека.'); return; }
  const круг = перемешать(имена);
  const пары = круг.map((и, n) => [и, круг[(n + 1) % круг.length]]);
  const п = параметры({});
  const карточки = п.карточки !== false;
  const место = await местоДля(сп.в, карточки ? 5 : 2, Math.max(пары.length + 2, карточки ? Math.ceil(пары.length / 2) * 4 + 1 : 0));
  if(!место){ панель.сообщение('Справа от списка нет свободного места.'); return; }
  const {r, c} = место;
  /* пары — по алфавиту дарящих, а не по кругу: так из таблицы не видно цепочку целиком */
  const поАлфавиту = пары.slice().sort((a, b) => a[0].localeCompare(b[0], 'ru'));
  написать(r, c, 'Тайный Санта ' + сейчас() + ': ' + пары.length + ' чел.', ЗАГ);
  написать(r + 1, c, 'Кто дарит', Object.assign({fill: '#eef3fe', гр: ТОНКАЯ}, ЗАГ)); написать(r + 1, c + 1, 'Кому', Object.assign({fill: '#eef3fe', гр: ТОНКАЯ}, ЗАГ));
  поАлфавиту.forEach(([кто, кому], n) => { написать(r + 2 + n, c, кто, {гр: ТОНКАЯ}); написать(r + 2 + n, c + 1, кому, {гр: ТОНКАЯ}); });
  const шир = Math.max(16, Math.min(36, Math.max(...имена.map(x => x.length)) + 2));
  Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c, 0, c + 1)).SetColumnWidth(шир);
  if(карточки){
    /* карточки для вырезания: две в ряд, у каждой рамка */
    const кс = c + 3;
    Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, кс, 0, кс + 1)).SetColumnWidth(Math.max(26, шир + 6));
    поАлфавиту.forEach(([кто, кому], n) => {
      const rr = r + 1 + Math.floor(n / 2) * 4, cc = кс + n % 2;
      const верх = {в: {вид: 'штрих', цвет: '#9aa4b5'}, л: {вид: 'штрих', цвет: '#9aa4b5'}, п: {вид: 'штрих', цвет: '#9aa4b5'}};
      const низ = {н: {вид: 'штрих', цвет: '#9aa4b5'}, л: {вид: 'штрих', цвет: '#9aa4b5'}, п: {вид: 'штрих', цвет: '#9aa4b5'}};
      написать(rr, cc, '🎁 ' + кто, {b: 1, size: 12, гр: верх, align: 'center'});
      написать(rr + 1, cc, 'вы — Тайный Санта для', {size: 9, color: '#5b6b86', align: 'center', гр: {л: верх.л, п: верх.п}});
      написать(rr + 2, cc, кому, {b: 1, size: 13, color: '#b42318', align: 'center', гр: низ});
    });
  }
  панель.сообщение('Пары готовы: ' + пары.length + ' человек по одному кругу — никто не дарит сам себе. Таблица' + (карточки ? ' и карточки для вырезания' : '') + ' — в ' + АДРЕС(r, c) + '.'
    + (сп.повторы.length ? ' Повторы в списке убраны: ' + сп.повторы.slice(0, 3).join(', ') + '.' : ''));
}

/* --- лото --- */
/* Русское лото: 3 ряда × 9 столбцов, в каждом ряду 5 чисел, в столбце k — числа десятка k (первый 1–9, последний 80–90). */
function карточкаЛото(){
  for(let попытка = 0; попытка < 2000; попытка++){
    const сетка = [0, 1, 2].map(() => new Array(9).fill(0));
    let ок = true;
    for(let r = 0; r < 3 && ок; r++){
      /* в каждом ряду 5 случайных столбцов; потом проверим, что пустых столбцов нет */
      const ст = перемешать([0, 1, 2, 3, 4, 5, 6, 7, 8]).slice(0, 5);
      for(const c of ст) сетка[r][c] = 1;
    }
    for(let c = 0; c < 9; c++) if(!(сетка[0][c] + сетка[1][c] + сетка[2][c])) ок = false;
    if(!ок) continue;
    for(let c = 0; c < 9; c++){
      const от = c === 0 ? 1 : c * 10, до = c === 8 ? 90 : c * 10 + 9;
      const сколько = сетка[0][c] + сетка[1][c] + сетка[2][c];
      const числа = перемешать(Array.from({length: до - от + 1}, (_, i) => от + i)).slice(0, сколько).sort((a, b) => a - b);
      let k = 0; for(let r = 0; r < 3; r++) if(сетка[r][c]) сетка[r][c] = числа[k++]; else сетка[r][c] = '';
    }
    return сетка;
  }
  return null;
}
/* Бинго: 5×5, столбцы Б-И-Н-Г-О по 15 чисел, в центре свободная клетка. */
function карточкаБинго(){
  const сетка = [0, 1, 2, 3, 4].map(() => new Array(5).fill(''));
  for(let c = 0; c < 5; c++){
    const числа = перемешать(Array.from({length: 15}, (_, i) => c * 15 + 1 + i)).slice(0, 5);
    for(let r = 0; r < 5; r++) сетка[r][c] = числа[r];
  }
  сетка[2][2] = '★';
  return сетка;
}
async function Карточки(){
  const п = параметры({});
  const бинго = String(п.видЛото || '').startsWith('Бинго');
  const сколько = Math.max(1, Math.min(60, Math.floor(+п.карточек || 6)));
  const ш = бинго ? 5 : 9, в = бинго ? 5 : 3;
  const в0 = книга.выделение || {r1: 1, c1: 1};
  const r0 = в0.r1 - 1, c0 = в0.c1 - 1;
  const рядов = Math.ceil(сколько / 2), высота = рядов * (в + 2), ширина = 2 * ш + 1;
  if(!(await областьПуста(r0, c0, r0 + высота - 1, c0 + ширина - 1))){
    if(!(await диалог.вопрос('Карточки займут ' + ОБЛАСТЬ(r0, c0, r0 + высота - 1, c0 + ширина - 1) + ', а там уже что-то есть. Положить поверх? (Лучше — на пустой лист: щёлкните там клетку и нажмите снова.)'))) return;
  }
  const карты = [];
  Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r0, c0, r0, c0 + ширина - 1)).SetColumnWidth(бинго ? 40 / 7 : 34 / 7);
  Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r0, c0 + ш, r0, c0 + ш)).SetColumnWidth(14 / 7);
  for(let n = 0; n < сколько; n++){
    const сетка = бинго ? карточкаБинго() : карточкаЛото();
    const r = r0 + Math.floor(n / 2) * (в + 2), c = c0 + (n % 2) * (ш + 1);
    написать(r, c, (бинго ? 'Бинго' : 'Лото') + ' · карточка № ' + (n + 1), {b: 1, size: 10, color: '#5b6b86'});
    for(let rr = 0; rr < в; rr++) for(let cc = 0; cc < ш; cc++){
      const v = сетка[rr][cc];
      написать(r + 1 + rr, c + cc, v, {b: 1, size: 13, align: 'center', valign: 'middle', color: '#151c2e', гр: РАМКА('тонкая', '#151c2e')});
    }
    Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r + 1, c0, r + в, c0)).SetRowHeight(бинго ? 30 : 26);
    карты.push({r: r + 1, c, сетка});
  }
  await обновитьВысоты();
  лист().запомнить(ПАМЯТЬ_ЛОТО, {бинго, карты, вытянуто: [], всего: бинго ? 75 : 90});
  показатьБочонки();
  панель.сообщение('Карточек: ' + сколько + ' (' + (бинго ? 'бинго 1–75' : 'русское лото 1–90') + '). Печать — выделите их и «Печать». Ведущий тянет «Достать бочонок»: вытянутые числа на карточках станут красными.');
}
function показатьБочонки(){
  let м = null; try { м = лист().память(ПАМЯТЬ_ЛОТО); } catch(e){}
  if(!м){ панель.список('вытянуто', [['Бочонки', 'сначала сделайте карточки на этом листе']]); return; }
  панель.список('вытянуто', [['Вытянуто', м.вытянуто.length + ' из ' + м.всего], ['По порядку', м.вытянуто.join(', ') || '—'],
    ['По возрастанию', м.вытянуто.slice().sort((a, b) => a - b).join(', ') || '—']]);
}
function Бочонок(){
  let м = null; try { м = лист().память(ПАМЯТЬ_ЛОТО); } catch(e){}
  if(!м){ панель.сообщение('Сначала сделайте карточки на этом листе.'); return; }
  const остались = []; for(let x = 1; x <= м.всего; x++) if(!м.вытянуто.includes(x)) остались.push(x);
  if(!остались.length){ панель.сообщение('Все бочонки вытянуты.'); return; }
  const x = остались[случайное(остались.length)];
  м.вытянуто.push(x);
  /* число на карточках — красным */
  for(const к of м.карты) к.сетка.forEach((ряд, rr) => ряд.forEach((v, cc) => { if(v === x) клетка(к.r + rr, к.c + cc).стиль = {color: '#dc2626', i: 1}; }));
  лист().запомнить(ПАМЯТЬ_ЛОТО, м);
  const буква = м.бинго ? 'БИНГО'[Math.floor((x - 1) / 15)] + '-' : '';
  панель.поле('бочонок', [{текст: '  ' + буква + x + '  ', жирный: true, фон: '#fde68a', цвет: '#151c2e'}, {текст: '  ход ' + м.вытянуто.length, цвет: '#5b6b86'}]);
  показатьБочонки();
  /* кто заполнил ряд — подсказываем ведущему */
  const полные = [];
  м.карты.forEach((к, n) => к.сетка.forEach((ряд, rr) => { const числа = ряд.filter(v => typeof v === 'number'); if(числа.length && числа.every(v => м.вытянуто.includes(v)) && числа.includes(x)) полные.push('№ ' + (n + 1) + ' (ряд ' + (rr + 1) + ')'); }));
  панель.сообщение('Бочонок: ' + буква + x + '.' + (полные.length ? ' Закрыт ряд: ' + полные.join(', ') + '!' : ''));
}
function Старт(){ показатьБочонки(); }
